('rec6YGCIgBy3v5nte', '2025-12-10', 8, 0, NULL, 'December 10, 2025

CORESITE SV9 Phase 3 General Notes Review:

Install 6” conduit below grade with minimum 3 conduit containing 1 ¼” innerduct and 3 conduits containing 2” innerduct
Provide Fire-rated Plywood on all walls of each POE. See Archi.
Roof Provision Rigid Steel Conduit shall have Pull string, cap and seal
Single mode fiber optic cable installed in conduit is non armored
Conduit runs more than 100’ should have pull box
All conduit ends should have bushing
Cable Tray should be supported by cantilever brackets, Unistrut trapeze, & individual rod suspension brackets
Trays and wireways shall be supported on 5’ centers and supports must be within 2’ of any fitting
For conduits with internal diameter <2” Inside radius is 6X the inside diameter if EMT 10X if PVC
For conduits with internal diameter >2” Inside radius is 10X the inside diameter
Pull boxes shall not be used for splicing cable or used in lieu of a conduit bend
Bond SRG with #10 Bare copper ground conductor with maximum every 60’
Typical 4” conduit innerduct – (3) 1.25” HDPE - Split Duct Plug and Inside vault leave 24”( diff between 4” and 1.25”) and 10ft pull tape
Leave 1’ slack in Cable Tray & Cat 6 UTP cables terminated with 8P/8C Connectors
All conduit fittings shall be bonded e.g. bushing
LF Pull box sizing chart & pathway labeling convention @ Page 8', 'Approved', '2025-12-10'),
